@Serializable
@JsonClassDiscriminator("type")
sealed interface WirePayment                                  // closed: formats known at compile time
@Serializable @SerialName("csv") data class CsvPayment(val raw: String) : WirePayment
@Serializable @SerialName("xml") data class XmlPayment(val document: String) : WirePayment

fun normalize(json: String): Payment =
    when (val wire = Json.decodeFromString<WirePayment>(json)) {   // router = serializer
        is CsvPayment -> CsvMap.toPayment(wire.raw)                // one translator per format
        is XmlPayment -> XmlMap.toPayment(wire.document)           // exhaustive when
    }
